"use client";

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';

export default function RegistrationList() {
  const router = useRouter();
  const [registrations, setRegistrations] = useState([]); // State to hold registration data
  const [loading, setLoading] = useState(true); // State to manage loading status
  const [searchQuery, setSearchQuery] = useState(''); // State for search input
  const [stats, setStats] = useState(null); // State to hold statistics data
  const [page, setPage] = useState(1); // State for pagination
  const [pagination, setPagination] = useState(null); // State to hold pagination info

  // Fetch registrations and stats when the component mounts or page changes
  useEffect(() => {
    fetchRegistrations();
    fetchStats();
  }, [page]);

  // Function to fetch registrations from the API
  const fetchRegistrations = async () => {
    try {
      const response = await fetch(`http://localhost:3000/api/registrations?page=${page}&limit=10`);
      const data = await response.json();
      setRegistrations(data.data || []); // Set registrations data
      setPagination(data.pagination); // Set pagination data
    } catch (err) {
      console.error('Error fetching registrations:', err);
    } finally {
      setLoading(false); // Set loading to false after fetching
    }
  };

  // Function to fetch statistics from the API
  const fetchStats = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/registrations-stats');
      const data = await response.json();
      setStats(data.data); // Set statistics data
    } catch (err) {
      console.error('Error fetching stats:', err);
    }
  };

  // Function to handle search functionality
  const handleSearch = async () => {
    if (!searchQuery.trim()) {
      fetchRegistrations(); // If search query is empty, fetch all registrations
      return;
    }

    try {
      const response = await fetch(`http://localhost:3000/api/registrations/search/${searchQuery}`);
      const data = await response.json();
      setRegistrations(data.data || []); // Set registrations based on search
    } catch (err) {
      console.error('Search error:', err);
    }
  };

  // Function to handle deletion of a registration
  const handleDelete = async (id) => {
    if (!confirm('Are you sure you want to delete this registration?')) return;

    try {
      await fetch(`http://localhost:3000/api/registrations/${id}`, {
        method: 'DELETE'
      });
      fetchRegistrations(); // Refresh registrations after deletion
      fetchStats(); // Refresh stats after deletion
    } catch (err) {
      console.error('Delete error:', err);
      alert('Failed to delete registration');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-gray-800">BEC Registrations</h1>
          <button
            onClick={() => router.push('/registration')}
            className="bg-indigo-600 text-white py-2 px-6 rounded-lg hover:bg-indigo-700 transition"
          >
            + New Registration
          </button>
        </div>

        {stats && (
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Statistics</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="text-center p-4 bg-blue-50 rounded">
                <p className="text-3xl font-bold text-blue-600">{stats.total}</p>
                <p className="text-sm text-gray-600">Total Registrations</p>
              </div>
              {stats.byUnit?.slice(0, 3).map((unit, idx) => (
                <div key={idx} className="text-center p-4 bg-green-50 rounded">
                  <p className="text-3xl font-bold text-green-600">{unit.count}</p>
                  <p className="text-sm text-gray-600">{unit.unit_in_BEC}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="bg-white rounded-lg shadow p-4 mb-6">
          <div className="flex gap-2">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)} // Update search query state
              onKeyPress={(e) => e.key === 'Enter' && handleSearch()} // Trigger search on Enter key
              placeholder="Search by name, email, or unit..."
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button
              onClick={handleSearch} // Trigger search on button click
              className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 transition"
            >
              Search
            </button>
            <button
              onClick={fetchRegistrations} // Clear search and fetch all registrations
              className="bg-gray-600 text-white px-6 py-2 rounded-lg hover:bg-gray-700 transition"
            >
              Clear
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow overflow-hidden">
          {loading ? (
            <div className="p-8 text-center">Loading...</div>
          ) : registrations.length === 0 ? (
            <div className="p-8 text-center text-gray-500">No registrations found</div>
          ) : (
            <>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">ID</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Age</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Email</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Mobile</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">BEC Unit</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {registrations.map((reg) => (
                      <tr key={reg.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 text-sm text-gray-900">{reg.id}</td>
                        <td className="px-6 py-4 text-sm text-gray-900">{reg.first_name} {reg.last_name}</td>
                        <td className="px-6 py-4 text-sm text-gray-900">{reg.age}</td>
                        <td className="px-6 py-4 text-sm text-gray-900">{reg.email}</td>
                        <td className="px-6 py-4 text-sm text-gray-900">{reg.mobile}</td>
                        <td className="px-6 py-4 text-sm text-gray-900">{reg.unit_in_BEC}</td>
                        <td className="px-6 py-4 text-sm">
                          <button
                            onClick={() => handleDelete(reg.id)} // Trigger delete for the specific registration
                            className="text-red-600 hover:text-red-800"
                          >
                            Delete
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              
              {pagination && (
                <div className="bg-gray-50 px-6 py-4 flex items-center justify-between border-t">
                  <div className="text-sm text-gray-700">
                    Page {pagination.page} of {pagination.totalPages} ({pagination.total} total)
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => setPage(p => Math.max(1, p - 1))} // Go to previous page
                      disabled={page === 1}
                      className="px-4 py-2 border rounded-lg disabled:opacity-50 hover:bg-gray-100"
                    >
                      Previous
                    </button>
                    <button
                      onClick={() => setPage(p => Math.min(pagination.totalPages, p + 1))} // Go to next page
                      disabled={page === pagination.totalPages}
                      className="px-4 py-2 border rounded-lg disabled:opacity-50 hover:bg-gray-100"
                    >
                      Next
                    </button>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}